import React, { useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { api } from './api';
import AuthPage from './pages/AuthPage';
import AdminPage from './pages/AdminPage';
import './App.css';

const Store = () => {
  const [products, setProducts] = useState([]);
  const [user, setUser] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ title: '', price: '', category: '', description: '' });
  const [editId, setEditId] = useState(null);
  const navigate = useNavigate();

  // Загрузка данных при старте
  useEffect(() => {
    // 1. ТОВАРЫ ГРУЗИМ СРАЗУ (ДЛЯ ВСЕХ)
    api.getProducts()
      .then(setProducts)
      .catch(err => console.error("Ошибка загрузки товаров:", err));

    // 2. ПРОВЕРЯЕМ АВТОРИЗАЦИЮ (КТО ЗАШЕЛ?)
    const token = localStorage.getItem('accessToken');
    if (token) {
      api.getMe()
        .then(userData => setUser(userData))
        .catch(() => {
          localStorage.clear();
          setUser(null);
        });
    }
  }, []);

  const refreshProducts = () => api.getProducts().then(setProducts);

  const handleSave = async (e) => {
    e.preventDefault();
    try {
      if (editId) await api.updateProduct(editId, formData);
      else await api.createProduct(formData);
      setShowModal(false);
      setEditId(null);
      setFormData({ title: '', price: '', category: '', description: '' });
      refreshProducts();
    } catch (err) {
      alert("Ошибка! Проверьте права доступа.");
    }
  };

  const onEdit = (p) => {
    setEditId(p.id);
    setFormData({ title: p.title, price: p.price, category: p.category, description: p.description });
    setShowModal(true);
  };

  const onDelete = async (id) => {
    if (window.confirm("Удалить товар?")) {
      try {
        await api.deleteProduct(id);
        refreshProducts();
      } catch (err) {
        alert("Только Администратор может удалять товары!");
      }
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    setUser(null);
    window.location.reload(); // Перезагрузка для чистоты состояния
  };

  return (
    <div className="store">
      <header className="header">
        <div className="container header-flex" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div className="logo">
            <h1>Nail Store</h1>
            {user ? (
              <p style={{ color: '#d4418e', fontWeight: '600' }}>
                Привет, {user.email} <span style={{ color: '#6b7280', fontSize: '12px' }}>({user.role})</span>
              </p>
            ) : (
              <p>Добро пожаловать в наш магазин!</p>
            )}
          </div>

          <div style={{ display: 'flex', gap: '10px' }}>
            {!user ? (
              // Кнопка для гостей
              <button className="btn-add" onClick={() => navigate('/login')} style={{ background: '#d4418e' }}>
                Войти в аккаунт
              </button>
            ) : (
              // Кнопки для авторизованных
              <>
                {user.role === 'admin' && (
                  <button className="btn-add" style={{ background: '#1f2937' }} onClick={() => navigate('/admin')}>
                    Управление пользователями
                  </button>
                )}
                {(user.role === 'admin' || user.role === 'seller') && (
                  <button className="btn-add" onClick={() => setShowModal(true)}>
                    + Добавить товар
                  </button>
                )}
                <button className="btn-add" style={{ background: '#9ca3af' }} onClick={handleLogout}>
                  Выход
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      {/* Модальное окно (Форма) */}
      {showModal && (
        <div className="modal">
          <div className="modal-box">
            <h2>{editId ? "Редактировать товар" : "Новый товар"}</h2>
            <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <input placeholder="Название" value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} required />
              <input placeholder="Цена" type="number" value={formData.price} onChange={e => setFormData({ ...formData, price: e.target.value })} required />
              <input placeholder="Категория" value={formData.category} onChange={e => setFormData({ ...formData, category: e.target.value })} />
              <div className="form-btns" style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                <button type="submit" className="btn-save" style={{ flex: 1 }}>Сохранить</button>
                <button type="button" className="btn-cancel" style={{ flex: 1 }} onClick={() => { setShowModal(false); setEditId(null); }}>Отмена</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* СЕТКА ТОВАРОВ (ВИДНА ВСЕМ!) */}
      <div className="grid container" style={{ marginTop: '30px' }}>
        {products.length === 0 ? (
          <p style={{ textAlign: 'center', width: '100%' }}>Товары не найдены...</p>
        ) : (
          products.map(p => (
            <div key={p.id} className="card">
              <div className="card-top" style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span className="tag">{p.category || 'Nail'}</span>
                
                {/* Кнопки управления (только для тех, у кого есть права) */}
                <div className="actions">
                  {user && (user.role === 'admin' || user.role === 'seller') && (
                    <button className="act-btn edit" onClick={() => onEdit(p)}>✎</button>
                  )}
                  {user && user.role === 'admin' && (
                    <button className="act-btn del" onClick={() => onDelete(p.id)}>×</button>
                  )}
                </div>
              </div>
              
              <h3>{p.title}</h3>
              <p style={{ fontSize: '14px', color: '#6b7280', margin: '10px 0' }}>{p.description}</p>
              <div className="info">
                <span className="price">{p.price} ₽</span>
              </div>
              <button className="btn-cart" style={{ width: '100%', marginTop: '15px' }}>В корзину</button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

// Роутер
function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<AuthPage />} />
        <Route path="/admin" element={<AdminPage />} />
        <Route path="/" element={<Store />} />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
